-- Database structure for "My Finances" (public schema).
-- Only for a NEW, empty Supabase project: paste it whole into the SQL Editor and run it.
-- It is generated by the public.schema_sql() function on every backup.
begin;
do $g$ begin
  if exists (select 1 from pg_tables where schemaname = 'public') then
    raise exception 'This project already has tables: schema.sql is only for a new, empty project';
  end if;
end $g$;
set local check_function_bodies = off;

-- ---------- Tables ----------
create table public.asset_types (
  id uuid default gen_random_uuid() not null,
  name text not null,
  valuation text not null,
  annual_return numeric default 0 not null,
  created_at timestamp with time zone default now() not null,
  user_id uuid default auth.uid() not null,
  identifier text default 'none'::text not null,
  has_maturity boolean default false not null,
  base_key text
);

create table public.assets (
  id uuid default gen_random_uuid() not null,
  name text not null,
  ticker text,
  currency text default 'EUR'::text not null,
  created_at timestamp with time zone default now() not null,
  type_id uuid not null,
  platform_id uuid,
  category_id uuid,
  annual_return numeric,
  user_id uuid default auth.uid() not null,
  isin text,
  maturity_date date,
  price_status text,
  price_updated_at timestamp with time zone,
  price_source text default 'yahoo'::text not null,
  monthly_contribution numeric(12,2) default 0 not null
);

create table public.bank_accounts (
  id uuid default gen_random_uuid() not null,
  created_at timestamp with time zone default now() not null,
  user_id uuid default auth.uid() not null,
  connection_id uuid not null,
  uid text not null,
  fingerprint text not null,
  name text,
  iban_last4 text,
  currency text,
  account_id uuid
);

create table public.bank_connections (
  id uuid default gen_random_uuid() not null,
  created_at timestamp with time zone default now() not null,
  user_id uuid default auth.uid() not null,
  bank text not null,
  country text default 'ES'::text not null,
  status text default 'pending'::text not null,
  state text,
  session_id text,
  valid_until timestamp with time zone,
  last_fetch_at timestamp with time zone,
  last_error text
);

create table public.bank_rules (
  id uuid default gen_random_uuid() not null,
  created_at timestamp with time zone default now() not null,
  user_id uuid default auth.uid() not null,
  text text not null,
  category_id uuid,
  bizum boolean default false not null,
  is_transfer boolean default false not null,
  other_account_id uuid,
  description text
);

create table public.bank_transactions (
  id uuid default gen_random_uuid() not null,
  created_at timestamp with time zone default now() not null,
  user_id uuid default auth.uid() not null,
  bank_account_id uuid not null,
  bank_ref text not null,
  date date not null,
  amount numeric(12,2) not null,
  currency text default 'EUR'::text not null,
  description text,
  counterparty text,
  status text default 'pending'::text not null,
  movement_id uuid,
  auto text,
  value_date date,
  transaction_date date
);

create table public.capture_cards (
  id uuid default gen_random_uuid() not null,
  card text not null,
  account_id uuid,
  created_at timestamp with time zone default now() not null,
  user_id uuid default auth.uid() not null
);

create table public.capture_tokens (
  id uuid default gen_random_uuid() not null,
  token_hash text not null,
  last_used_at timestamp with time zone,
  created_at timestamp with time zone default now() not null,
  user_id uuid default auth.uid() not null
);

create table public.captures (
  id uuid default gen_random_uuid() not null,
  date date not null,
  amount numeric(12,2) not null,
  merchant text,
  card text,
  status text default 'open'::text not null,
  account_id uuid,
  movement_id uuid,
  bank_transaction_id uuid,
  created_at timestamp with time zone default now() not null,
  user_id uuid default auth.uid() not null
);

create table public.categories (
  id uuid default gen_random_uuid() not null,
  name text not null,
  created_at timestamp with time zone default now() not null,
  user_id uuid default auth.uid() not null
);

create table public.expense_categories (
  id uuid default gen_random_uuid() not null,
  name text not null,
  created_at timestamp with time zone default now() not null,
  user_id uuid default auth.uid() not null
);

create table public.favorites (
  id uuid default gen_random_uuid() not null,
  symbol text not null,
  name text not null,
  source text default 'yahoo'::text not null,
  currency text,
  created_at timestamp with time zone default now() not null,
  user_id uuid default auth.uid() not null
);

create table public.fee_schedules (
  id uuid default gen_random_uuid() not null,
  created_at timestamp with time zone default now() not null,
  user_id uuid default auth.uid() not null,
  platform_id uuid not null,
  type_id uuid not null,
  valid_from date default CURRENT_DATE not null,
  percent numeric default 0 not null,
  fixed numeric default 0 not null,
  minimum numeric default 0 not null,
  maximum numeric,
  fx_percent numeric default 0 not null
);

create table public.movements (
  id uuid default gen_random_uuid() not null,
  date date default CURRENT_DATE not null,
  type text not null,
  amount numeric not null,
  account_id uuid,
  target_account_id uuid,
  category_id uuid,
  bizum boolean default false not null,
  description text,
  created_at timestamp with time zone default now() not null,
  user_id uuid default auth.uid() not null,
  refund_of_id uuid
);

create table public.platforms (
  id uuid default gen_random_uuid() not null,
  name text not null,
  created_at timestamp with time zone default now() not null,
  user_id uuid default auth.uid() not null
);

create table public.prices (
  id uuid default gen_random_uuid() not null,
  asset_id uuid not null,
  date date not null,
  price numeric not null
);

create table public.transactions (
  id uuid default gen_random_uuid() not null,
  asset_id uuid not null,
  date date default CURRENT_DATE not null,
  type text default 'buy'::text not null,
  amount numeric default 0 not null,
  fee numeric default 0 not null,
  price numeric,
  units numeric,
  created_at timestamp with time zone default now() not null,
  account_id uuid,
  user_id uuid default auth.uid() not null,
  withholding numeric default 0 not null,
  factor numeric,
  notes text,
  switch_id uuid
);

-- ---------- Functions ----------
CREATE OR REPLACE FUNCTION public.return_to_inbox()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  update public.bank_transactions
     set status = 'pending', movement_id = null, auto = null
   where movement_id = old.id;
  return old;
end;
$function$;

CREATE OR REPLACE FUNCTION public.schema_sql()
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
with recursive
tables_ as (
  select c.oid, c.relname, c.relrowsecurity, c.relforcerowsecurity
  from pg_catalog.pg_class c
  where c.relnamespace = 'public'::regnamespace
    and c.relkind in ('r', 'p')
    and not exists (
      select 1 from pg_catalog.pg_depend d where d.objid = c.oid and d.deptype = 'e'
    )
),
views_ as (
  select c.oid, c.relname, c.reloptions
  from pg_catalog.pg_class c
  where c.relnamespace = 'public'::regnamespace and c.relkind = 'v'
),
-- A view that uses another view has to be created after it
uses as (
  select distinct r.ev_class as view_oid, d.refobjid as other
  from pg_catalog.pg_rewrite r
  join pg_catalog.pg_depend d
    on d.classid = 'pg_catalog.pg_rewrite'::regclass and d.objid = r.oid
  where r.ev_class in (select oid from views_)
    and d.refobjid in (select oid from views_)
    and d.refobjid <> r.ev_class
),
depth (oid, n) as (
  select oid, 0 from views_
  union all
  select u.view_oid, depth.n + 1 from uses u join depth on u.other = depth.oid where depth.n < 50
),
functions_ as (
  select p.oid, p.proname, p.proowner, p.proacl
  from pg_catalog.pg_proc p
  where p.pronamespace = 'public'::regnamespace
    and p.prokind in ('f', 'p')
    and not exists (
      select 1 from pg_catalog.pg_depend d where d.objid = p.oid and d.deptype = 'e'
    )
),
-- Supabase roles whose privileges are revoked before granting the ones there were
roles as (
  select string_agg(quote_ident(rolname), ', ' order by rolname) as list
  from pg_catalog.pg_roles
  where rolname in ('anon', 'authenticated', 'service_role')
),
privileges_ as (
  -- Tables and views
  select 1 as sort, c.relname::text as name,
    format('revoke all on table public.%I from public%s;', c.relname,
      coalesce(', ' || (select list from roles), ''))
    || coalesce((
      select string_agg(format(E'\ngrant %s on table public.%I to %s;', g.privs, c.relname, g.role), '' order by g.role)
      from (
        select case when a.grantee = 0 then 'public' else quote_ident(r.rolname) end as role,
          string_agg(lower(a.privilege_type), ', ' order by a.privilege_type) as privs
        from aclexplode(coalesce(c.relacl, acldefault('r', c.relowner))) a
        left join pg_catalog.pg_roles r on r.oid = a.grantee
        where a.grantee <> c.relowner
        group by 1
      ) g
    ), '') as text
  from pg_catalog.pg_class c
  where c.oid in (select oid from tables_ union all select oid from views_)
  union all
  -- Functions
  select 2, f.proname || pg_catalog.pg_get_function_identity_arguments(f.oid),
    format('revoke all on function public.%I(%s) from public%s;', f.proname,
      pg_catalog.pg_get_function_identity_arguments(f.oid),
      coalesce(', ' || (select list from roles), ''))
    || coalesce((
      select string_agg(format(E'\ngrant execute on function public.%I(%s) to %s;', f.proname,
        pg_catalog.pg_get_function_identity_arguments(f.oid),
        case when a.grantee = 0 then 'public' else quote_ident(r.rolname) end), '' order by r.rolname nulls first)
      from aclexplode(coalesce(f.proacl, acldefault('f', f.proowner))) a
      left join pg_catalog.pg_roles r on r.oid = a.grantee
      where a.grantee <> f.proowner and a.privilege_type = 'EXECUTE'
    ), '')
  from functions_ f
)
select concat_ws(E'\n\n',
  E'-- Database structure for "My Finances" (public schema).\n'
  || E'-- Only for a NEW, empty Supabase project: paste it whole into the SQL Editor and run it.\n'
  || E'-- It is generated by the public.schema_sql() function on every backup.\n'
  || E'begin;\n'
  || E'do $g$ begin\n'
  || E'  if exists (select 1 from pg_tables where schemaname = ''public'') then\n'
  || E'    raise exception ''This project already has tables: schema.sql is only for a new, empty project'';\n'
  || E'  end if;\n'
  || E'end $g$;\n'
  || 'set local check_function_bodies = off;',

  -- Custom types (enum)
  (select '-- ---------- Types ----------' || E'\n' || string_agg(
      format('create type public.%I as enum (%s);', t.typname,
        (select string_agg(quote_literal(e.enumlabel), ', ' order by e.enumsortorder)
         from pg_catalog.pg_enum e where e.enumtypid = t.oid)),
      E'\n' order by t.typname)
   from pg_catalog.pg_type t
   where t.typnamespace = 'public'::regnamespace and t.typtype = 'e'
   having count(*) > 0),

  -- Tables and their columns
  (select '-- ---------- Tables ----------' || E'\n' || string_agg(
      format(E'create table public.%I (\n%s\n);', t.relname,
        (select string_agg(
            format('  %I %s', a.attname, pg_catalog.format_type(a.atttypid, a.atttypmod))
            || case a.attidentity
                 when 'a' then ' generated always as identity'
                 when 'd' then ' generated by default as identity'
                 else '' end
            || case
                 when a.attgenerated = 's' then ' generated always as (' || pg_catalog.pg_get_expr(ad.adbin, ad.adrelid) || ') stored'
                 when ad.adbin is not null then ' default ' || pg_catalog.pg_get_expr(ad.adbin, ad.adrelid)
                 else '' end
            || case when a.attnotnull then ' not null' else '' end,
            E',\n' order by a.attnum)
         from pg_catalog.pg_attribute a
         left join pg_catalog.pg_attrdef ad on ad.adrelid = a.attrelid and ad.adnum = a.attnum
         where a.attrelid = t.oid and a.attnum > 0 and not a.attisdropped)),
      E'\n\n' order by t.relname)
   from tables_ t
   having count(*) > 0),

  -- Functions (this one too)
  (select '-- ---------- Functions ----------' || E'\n' || string_agg(
      rtrim(pg_catalog.pg_get_functiondef(f.oid), E'\n') || ';', E'\n\n' order by f.proname, f.oid)
   from functions_ f
   having count(*) > 0),

  -- Constraints: keys, unique values, checks and relationships between tables
  (select '-- ---------- Constraints ----------' || E'\n' || string_agg(
      format('alter table public.%I add constraint %I %s;', t.relname, co.conname,
        pg_catalog.pg_get_constraintdef(co.oid)),
      E'\n' order by
        case co.contype when 'p' then 1 when 'u' then 2 when 'x' then 3 when 'c' then 4 else 5 end,
        t.relname, co.conname)
   from pg_catalog.pg_constraint co
   join tables_ t on t.oid = co.conrelid
   where co.contype in ('p', 'u', 'x', 'c', 'f')
   having count(*) > 0),

  -- Indexes that don't come from a constraint
  (select '-- ---------- Indexes ----------' || E'\n' || string_agg(
      pg_catalog.pg_get_indexdef(i.indexrelid) || ';', E'\n' order by t.relname, i.indexrelid::regclass::text)
   from pg_catalog.pg_index i
   join tables_ t on t.oid = i.indrelid
   where not exists (
     select 1 from pg_catalog.pg_constraint co
     where co.conindid = i.indexrelid and co.conrelid = i.indrelid and co.contype in ('p', 'u', 'x')
   )
   having count(*) > 0),

  -- Views, each one after the ones it uses
  (select '-- ---------- Views ----------' || E'\n' || string_agg(
      format(E'create view public.%I%s as\n%s', v.relname,
        case when v.reloptions is not null
          then ' with (' || array_to_string(v.reloptions, ', ') || ')' else '' end,
        pg_catalog.pg_get_viewdef(v.oid, true)),
      E'\n\n' order by (select max(n) from depth where depth.oid = v.oid), v.relname)
   from views_ v
   having count(*) > 0),

  -- Security: each row is only visible to its owner
  (select '-- ---------- Security (RLS) ----------' || E'\n' || string_agg(
      format('alter table public.%I enable row level security;', t.relname)
      || case when t.relforcerowsecurity
           then format(E'\nalter table public.%I force row level security;', t.relname) else '' end,
      E'\n' order by t.relname)
   from tables_ t
   where t.relrowsecurity
   having count(*) > 0),

  (select '-- ---------- Policies ----------' || E'\n' || string_agg(
      format('create policy %I on public.%I as %s for %s to %s', p.policyname, p.tablename,
        lower(p.permissive), lower(p.cmd),
        (select string_agg(case when r = 'public' then 'public' else quote_ident(r) end, ', ')
         from unnest(p.roles) r))
      || coalesce(E'\n  using (' || p.qual || ')', '')
      || coalesce(E'\n  with check (' || p.with_check || ')', '') || ';',
      E'\n' order by p.tablename, p.policyname)
   from pg_catalog.pg_policies p
   where p.schemaname = 'public'
   having count(*) > 0),

  -- Privileges of the Supabase roles
  (select '-- ---------- Privileges ----------' || E'\n'
      || string_agg(text, E'\n' order by sort, name)
   from privileges_
   having count(*) > 0),

  -- Triggers
  (select '-- ---------- Triggers ----------' || E'\n' || string_agg(
      pg_catalog.pg_get_triggerdef(tg.oid) || ';', E'\n' order by t.relname, tg.tgname)
   from pg_catalog.pg_trigger tg
   join tables_ t on t.oid = tg.tgrelid
   where not tg.tgisinternal
   having count(*) > 0),

  'commit;'
) || E'\n';
$function$;

-- ---------- Constraints ----------
alter table public.asset_types add constraint asset_types_pkey PRIMARY KEY (id);
alter table public.assets add constraint assets_pkey PRIMARY KEY (id);
alter table public.bank_accounts add constraint bank_accounts_pkey PRIMARY KEY (id);
alter table public.bank_connections add constraint bank_connections_pkey PRIMARY KEY (id);
alter table public.bank_rules add constraint bank_rules_pkey PRIMARY KEY (id);
alter table public.bank_transactions add constraint bank_transactions_pkey PRIMARY KEY (id);
alter table public.capture_cards add constraint capture_cards_pkey PRIMARY KEY (id);
alter table public.capture_tokens add constraint capture_tokens_pkey PRIMARY KEY (id);
alter table public.captures add constraint captures_pkey PRIMARY KEY (id);
alter table public.categories add constraint categories_pkey PRIMARY KEY (id);
alter table public.expense_categories add constraint expense_categories_pkey PRIMARY KEY (id);
alter table public.favorites add constraint favorites_pkey PRIMARY KEY (id);
alter table public.fee_schedules add constraint fee_schedules_pkey PRIMARY KEY (id);
alter table public.movements add constraint movements_pkey PRIMARY KEY (id);
alter table public.platforms add constraint platforms_pkey PRIMARY KEY (id);
alter table public.prices add constraint prices_pkey PRIMARY KEY (id);
alter table public.transactions add constraint transactions_pkey PRIMARY KEY (id);
alter table public.asset_types add constraint asset_types_user_base_key_key UNIQUE (user_id, base_key);
alter table public.asset_types add constraint asset_types_user_name_key UNIQUE (user_id, name);
alter table public.bank_accounts add constraint bank_accounts_fingerprint_key UNIQUE (user_id, fingerprint);
alter table public.bank_connections add constraint bank_connections_state_key UNIQUE (state);
alter table public.bank_rules add constraint bank_rules_text_key UNIQUE (user_id, text);
alter table public.bank_transactions add constraint bank_transactions_bank_ref_key UNIQUE (bank_account_id, bank_ref);
alter table public.capture_cards add constraint capture_cards_user_card_key UNIQUE (user_id, card);
alter table public.capture_tokens add constraint capture_tokens_token_hash_key UNIQUE (token_hash);
alter table public.categories add constraint categories_user_name_key UNIQUE (user_id, name);
alter table public.expense_categories add constraint expense_categories_user_name_key UNIQUE (user_id, name);
alter table public.favorites add constraint favorites_user_symbol_key UNIQUE (user_id, symbol);
alter table public.fee_schedules add constraint fee_schedules_user_platform_type_valid_from_key UNIQUE (user_id, platform_id, type_id, valid_from);
alter table public.platforms add constraint platforms_user_name_key UNIQUE (user_id, name);
alter table public.prices add constraint prices_asset_id_date_key UNIQUE (asset_id, date);
alter table public.asset_types add constraint asset_types_base_key_check CHECK ((base_key = ANY (ARRAY['bank_account'::text, 'savings_account'::text, 'term_deposit'::text, 'treasury_bills'::text, 'etf'::text, 'fund'::text, 'stock'::text, 'bond'::text, 'crypto'::text, 'pension_plan'::text, 'other'::text])));
alter table public.asset_types add constraint asset_types_identifier_check CHECK ((identifier = ANY (ARRAY['isin'::text, 'symbol'::text, 'none'::text])));
alter table public.asset_types add constraint asset_types_valuation_check CHECK ((valuation = ANY (ARRAY['market'::text, 'balance'::text])));
alter table public.assets add constraint assets_isin_check CHECK ((isin ~ '^[A-Z]{2}[A-Z0-9]{9}[0-9]$'::text));
alter table public.assets add constraint assets_monthly_contribution_check CHECK ((monthly_contribution >= (0)::numeric));
alter table public.assets add constraint assets_price_source_check CHECK ((price_source = ANY (ARRAY['yahoo'::text, 'ft'::text, 'manual'::text])));
alter table public.bank_connections add constraint bank_connections_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'active'::text, 'error'::text])));
alter table public.bank_rules add constraint bank_rules_is_transfer_check CHECK (((NOT is_transfer) OR (other_account_id IS NOT NULL)));
alter table public.bank_rules add constraint bank_rules_text_check CHECK ((length(btrim(text)) >= 3));
alter table public.bank_transactions add constraint bank_transactions_auto_check CHECK ((auto = ANY (ARRAY['recorded'::text, 'linked'::text])));
alter table public.bank_transactions add constraint bank_transactions_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'classified'::text, 'ignored'::text])));
alter table public.favorites add constraint favorites_source_check CHECK ((source = ANY (ARRAY['yahoo'::text, 'ft'::text])));
alter table public.fee_schedules add constraint fee_schedules_fixed_check CHECK ((fixed >= (0)::numeric));
alter table public.fee_schedules add constraint fee_schedules_fx_percent_check CHECK ((fx_percent >= (0)::numeric));
alter table public.fee_schedules add constraint fee_schedules_maximum_check CHECK (((maximum IS NULL) OR (maximum >= minimum)));
alter table public.fee_schedules add constraint fee_schedules_minimum_check CHECK ((minimum >= (0)::numeric));
alter table public.fee_schedules add constraint fee_schedules_percent_check CHECK ((percent >= (0)::numeric));
alter table public.movements add constraint movements_account_check CHECK (((type = ANY (ARRAY['expense'::text, 'income'::text])) OR (account_id IS NOT NULL)));
alter table public.movements add constraint movements_amount_check CHECK (((type = 'adjustment'::text) OR (amount > (0)::numeric)));
alter table public.movements add constraint movements_refund_check CHECK (((refund_of_id IS NULL) OR ((type = 'income'::text) AND (refund_of_id <> id))));
alter table public.movements add constraint movements_transfer_check CHECK ((((type = 'transfer'::text) AND (target_account_id IS NOT NULL) AND (target_account_id <> account_id)) OR ((type <> 'transfer'::text) AND (target_account_id IS NULL))));
alter table public.movements add constraint movements_type_check CHECK ((type = ANY (ARRAY['expense'::text, 'income'::text, 'transfer'::text, 'adjustment'::text])));
alter table public.transactions add constraint transactions_rules_check CHECK (((fee >= (0)::numeric) AND (withholding >= (0)::numeric) AND (((type = ANY (ARRAY['buy'::text, 'sell'::text])) AND (amount > (0)::numeric) AND (units > (0)::numeric) AND (price > (0)::numeric)) OR ((type = 'dividend'::text) AND (amount > (0)::numeric)) OR ((type = 'split'::text) AND (factor > (0)::numeric) AND (amount = (0)::numeric) AND (units IS NOT NULL)))));
alter table public.transactions add constraint transactions_switch_check CHECK (((switch_id IS NULL) OR (type = ANY (ARRAY['buy'::text, 'sell'::text]))));
alter table public.asset_types add constraint asset_types_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;
alter table public.captures add constraint captures_amount_check CHECK ((amount > (0)::numeric));
alter table public.captures add constraint captures_status_check CHECK ((status = ANY (ARRAY['open'::text, 'matched'::text, 'unmapped'::text, 'foreign'::text])));
alter table public.assets add constraint assets_category_id_fkey FOREIGN KEY (category_id) REFERENCES public.categories(id);
alter table public.assets add constraint assets_platform_id_fkey FOREIGN KEY (platform_id) REFERENCES public.platforms(id);
alter table public.assets add constraint assets_type_id_fkey FOREIGN KEY (type_id) REFERENCES public.asset_types(id);
alter table public.assets add constraint assets_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;
alter table public.bank_accounts add constraint bank_accounts_account_id_fkey FOREIGN KEY (account_id) REFERENCES public.assets(id) ON DELETE SET NULL;
alter table public.bank_accounts add constraint bank_accounts_connection_id_fkey FOREIGN KEY (connection_id) REFERENCES public.bank_connections(id) ON DELETE CASCADE;
alter table public.bank_accounts add constraint bank_accounts_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;
alter table public.bank_connections add constraint bank_connections_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;
alter table public.bank_rules add constraint bank_rules_category_id_fkey FOREIGN KEY (category_id) REFERENCES public.expense_categories(id) ON DELETE SET NULL;
alter table public.bank_rules add constraint bank_rules_other_account_id_fkey FOREIGN KEY (other_account_id) REFERENCES public.assets(id) ON DELETE CASCADE;
alter table public.bank_rules add constraint bank_rules_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;
alter table public.bank_transactions add constraint bank_transactions_bank_account_id_fkey FOREIGN KEY (bank_account_id) REFERENCES public.bank_accounts(id) ON DELETE CASCADE;
alter table public.bank_transactions add constraint bank_transactions_movement_id_fkey FOREIGN KEY (movement_id) REFERENCES public.movements(id) ON DELETE SET NULL;
