-- ---------- Views ----------
create view public.latest_prices with (security_invoker=true) as
 SELECT DISTINCT ON (asset_id) asset_id,
    date,
    price
   FROM public.prices
  ORDER BY asset_id, date DESC;

create view public.ledger_entries with (security_invoker=true) as
 SELECT movements.account_id,
    movements.date,
        CASE movements.type
            WHEN 'expense'::text THEN - movements.amount
            ELSE movements.amount
        END AS amount,
    movements.type AS source,
    movements.id AS ref_id
   FROM public.movements
  WHERE movements.account_id IS NOT NULL AND (movements.type = ANY (ARRAY['expense'::text, 'income'::text, 'adjustment'::text]))
UNION ALL
 SELECT movements.account_id,
    movements.date,
    - movements.amount AS amount,
    'transfer_out'::text AS source,
    movements.id AS ref_id
   FROM public.movements
  WHERE movements.type = 'transfer'::text
UNION ALL
 SELECT movements.target_account_id AS account_id,
    movements.date,
    movements.amount,
    'transfer_in'::text AS source,
    movements.id AS ref_id
   FROM public.movements
  WHERE movements.type = 'transfer'::text
UNION ALL
 SELECT transactions.account_id,
    transactions.date,
        CASE transactions.type
            WHEN 'buy'::text THEN - (transactions.amount + transactions.fee)
            WHEN 'sell'::text THEN transactions.amount - transactions.fee
            ELSE transactions.amount - transactions.withholding - transactions.fee
        END AS amount,
    transactions.type AS source,
    transactions.id AS ref_id
   FROM public.transactions
  WHERE transactions.account_id IS NOT NULL AND (transactions.type = ANY (ARRAY['buy'::text, 'sell'::text, 'dividend'::text]));

create view public.positions with (security_invoker=true) as
 SELECT asset_id,
    sum(
        CASE type
            WHEN 'buy'::text THEN units
            WHEN 'sell'::text THEN - units
            WHEN 'split'::text THEN units
            ELSE 0::numeric
        END) AS units,
    sum(
        CASE
            WHEN type = 'buy'::text THEN amount + fee
            ELSE 0::numeric
        END) AS bought,
    sum(
        CASE
            WHEN type = 'sell'::text THEN amount - fee
            ELSE 0::numeric
        END) AS sold,
    sum(
        CASE
            WHEN type = 'dividend'::text THEN amount - withholding - fee
            ELSE 0::numeric
        END) AS dividends,
    sum(fee) AS fees
   FROM public.transactions
  GROUP BY asset_id;

create view public.account_balances with (security_invoker=true) as
 SELECT a.id AS account_id,
    COALESCE(sum(le.amount), 0::numeric) AS balance
   FROM public.assets a
     JOIN public.asset_types t ON t.id = a.type_id
     LEFT JOIN public.ledger_entries le ON le.account_id = a.id
  WHERE t.valuation = 'balance'::text
  GROUP BY a.id;

