create policy "own asset prices only" on public.prices as permissive for all to authenticated
  using ((EXISTS ( SELECT 1
   FROM public.assets a
  WHERE ((a.id = prices.asset_id) AND (a.user_id = ( SELECT auth.uid() AS uid))))))
  with check ((EXISTS ( SELECT 1
   FROM public.assets a
  WHERE ((a.id = prices.asset_id) AND (a.user_id = ( SELECT auth.uid() AS uid))))));
create policy "own rows only" on public.transactions as permissive for all to authenticated
  using ((user_id = ( SELECT auth.uid() AS uid)))
